import { useEffect, useState } from "react";
import { useNavigate, useParams, Link } from "react-router-dom";
import { ArrowLeft, Maximize2, Minimize2, Loader2 } from "lucide-react";
import { toast } from "sonner";
import { getGame, gameEmbedUrl } from "@/lib/api";

export default function GamePlayerPage() {
  const { slug } = useParams();
  const navigate = useNavigate();
  const [game, setGame] = useState(null);
  const [loading, setLoading] = useState(true);
  const [notFound, setNotFound] = useState(false);
  const [immersive, setImmersive] = useState(false);

  useEffect(() => {
    (async () => {
      try {
        const data = await getGame(slug);
        setGame(data);
      } catch (e) {
        if (e?.response?.status === 404) {
          setNotFound(true);
        } else {
          console.error(e);
          toast.error("Could not load this game.");
        }
      } finally {
        setLoading(false);
      }
    })();
  }, [slug]);

  useEffect(() => {
    const onKey = (e) => {
      if (e.key === "Escape") {
        if (immersive) setImmersive(false);
        else navigate("/");
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [immersive, navigate]);

  if (loading) {
    return (
      <div className="min-h-screen grid place-items-center bg-[#fff7f0]">
        <div className="flex items-center gap-3 text-[#5c534d]">
          <Loader2 className="animate-spin text-[#ff6a00]" size={22} />
          <span className="font-medium">Loading game…</span>
        </div>
      </div>
    );
  }

  if (notFound || !game) {
    return (
      <div className="min-h-screen grid place-items-center bg-[#fff7f0] px-6">
        <div className="text-center max-w-md" data-testid="game-not-found">
          <h1 className="font-display text-3xl font-bold">Game not found</h1>
          <p className="mt-2 text-[#5c534d]">
            The game you&apos;re looking for isn&apos;t in our library.
          </p>
          <Link
            to="/"
            className="inline-flex items-center gap-2 mt-6 px-5 py-2.5 rounded-full bg-[#ff6a00] text-white text-sm font-semibold hover:bg-[#e85d00] transition-colors"
            data-testid="back-home-btn"
          >
            <ArrowLeft size={16} /> Back to library
          </Link>
        </div>
      </div>
    );
  }

  return (
    <div
      className="fixed inset-0 bg-[#1a1613] flex flex-col"
      data-testid="game-player"
    >
      {/* Top Bar */}
      {!immersive && (
        <div
          className="flex items-center justify-between px-4 sm:px-6 h-14 border-b border-white/10 bg-[#1a1613]"
          data-testid="game-player-topbar"
        >
          <div className="flex items-center gap-3 min-w-0">
            <button
              onClick={() => navigate("/")}
              className="flex items-center gap-1.5 text-sm font-medium text-white/80 hover:text-white transition-colors"
              data-testid="back-to-library-btn"
            >
              <ArrowLeft size={16} />
              <span className="hidden sm:inline">Library</span>
            </button>
            <span className="text-white/25">/</span>
            <h1
              className="font-display text-white font-semibold text-base sm:text-lg truncate"
              data-testid="game-title"
              title={game.name}
            >
              {game.name}
            </h1>
          </div>
          <button
            onClick={() => setImmersive(true)}
            className="inline-flex items-center gap-1.5 text-xs sm:text-sm font-semibold px-3 py-1.5 rounded-full bg-[#ff6a00] text-white hover:bg-[#e85d00] transition-colors"
            data-testid="immersive-btn"
            title="Immersive mode (Esc to exit)"
          >
            <Maximize2 size={14} />
            <span className="hidden sm:inline">Immersive</span>
          </button>
        </div>
      )}

      {/* Iframe */}
      <div className="relative flex-1 bg-black">
        <iframe
          data-testid="game-iframe"
          title={game.name}
          src={gameEmbedUrl(game.slug)}
          className="w-full h-full border-0 block"
          allow="autoplay; fullscreen; gamepad; pointer-lock; clipboard-write"
          allowFullScreen
        />
        {immersive && (
          <button
            onClick={() => setImmersive(false)}
            className="fixed top-4 right-4 z-50 grid place-items-center w-11 h-11 rounded-full bg-[#ff6a00] text-white shadow-lg hover:bg-[#e85d00] transition-colors"
            data-testid="exit-immersive-btn"
            title="Exit immersive mode (Esc)"
          >
            <Minimize2 size={18} />
          </button>
        )}
      </div>
    </div>
  );
}
